import { createTRPCClient, localLink, TRPCClientError } from '@trpc/client';
import { initTRPC, TRPCError } from '@trpc/server';
import { describe, expect, it } from 'vitest';

describe('localLink error data propagation', () => {
  it('propagates error shape and data', async () => {
    const t = initTRPC.create();
    const router = t.router({
      error: t.procedure.query(() => {
        throw new TRPCError({
          code: 'BAD_REQUEST',
          message: 'Custom error message',
          cause: new Error('Original cause'),
        });
      }),
    });

    const client = createTRPCClient<typeof router>({
      links: [localLink({ router })],
    });

    const err = await client.error.query().catch((e) => e);

    expect(err).toBeInstanceOf(TRPCClientError);
    expect(err.message).toBe('Custom error message');
    expect(err.shape).toBeDefined();
    expect(err.shape?.code).toBe(-32600); // BAD_REQUEST
  });
});

