import { createTRPCClient, localLink } from '@trpc/client';
import { initTRPC } from '@trpc/server';
import { describe, expect, it } from 'vitest';

describe('localLink transformer', () => {
  it('applies transformer to input and output', async () => {
    const transformer = {
      input: {
        serialize: (data: any) => {
          return { data, serialized: true };
        },
        deserialize: (data: any) => {
          if (!data.serialized) throw new Error('Not serialized');
          return data.data;
        },
      },
      output: {
        serialize: (data: any) => {
          return { data, serialized: true };
        },
        deserialize: (data: any) => {
          if (!data.serialized) throw new Error('Not serialized');
          return data.data;
        },
      },
    };

    const t = initTRPC.create({ transformer });
    const router = t.router({
      test: t.procedure.input(String).query(({ input }) => {
        return `received: ${input}`;
      }),
    });

    const client = createTRPCClient<typeof router>({
      links: [localLink({ router, transformer })],
    });

    // If it doesn't apply input transformer, the server will receive the raw string, 
    // but the server's input deserializer (run by trpc internally) will expect the serialized object.
    // Wait, trpc server SOMEWHERE calls transformer.input.deserialize.

    expect(await client.test.query('world')).toBe('received: world');
  });
});

